// Tests for the VP8 keyframe decoders against REAL lossy streams (TestData/Vp8Lossy, generated by
// scripts/images/make_vp8_lossy_fixtures.py).
//
// Fixtures: raw VP8 keyframes (the payload of a WebP 'VP8 ' chunk or an IVF frame) written by libwebp (Pillow + cwebp:
// quality 1..100, methods 0..6, 4 segments, simple and normal loop filter, sharpness 0..7, filter strength 0..100) and by
// libvpx (token partitions 2/4/8, versions 0..3, mode/ref loop-filter deltas), sizes 1x1 .. 640x480.
// THE TRUTH IS NEVER OUR OWN CODE: <name>.yuv (or .sha256 for the larger pictures) is the output of ffmpeg's native VP8
// decoder (-c:v vp8, yuv420p, verified native), which the generator also checked against ffmpeg's webp decoder and libwebp's
// dwebp for every libwebp-made file. manifest.csv carries the header facts an independent python parser read out of each
// file, so these tests can assert the corpus covers each keyframe feature.
//
// Every test collects ALL failures with the fixture name and the first differing plane/byte before failing.

using System.Security.Cryptography;
using SpawnDev.Codecs.Video.Vp8;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string Vp8LossyPrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Vp8Lossy.";

    private static string[] Vp8LossyFixtureNames()
    {
        var names = typeof(CodecsTestBase).Assembly.GetManifestResourceNames()
            .Where(n => n.StartsWith(Vp8LossyPrefix, StringComparison.Ordinal) && n.EndsWith(".vp8", StringComparison.Ordinal))
            .Select(n => n.Substring(Vp8LossyPrefix.Length, n.Length - Vp8LossyPrefix.Length - 4))
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        if (names.Length == 0) throw new InvalidOperationException("No VP8 lossy fixtures are embedded.");
        return names;
    }

    /// <summary>One manifest.csv row (header facts parsed by the generator's independent python parser).</summary>
    private sealed record Vp8LossyInfo(string Name, int Width, int Height, int Version, int FilterType, int FilterLevel,
        int Sharpness, bool LfDelta, bool Segmentation, int Log2Parts, int Q);

    private static List<Vp8LossyInfo> Vp8LossyManifest()
    {
        var text = System.Text.Encoding.UTF8.GetString(ReadEmbedded(Vp8LossyPrefix + "manifest.csv"));
        var rows = new List<Vp8LossyInfo>();
        foreach (var line in text.Split('\n').Skip(1))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            var c = line.TrimEnd('\r').Split(',');
            rows.Add(new Vp8LossyInfo(c[0], int.Parse(c[2]), int.Parse(c[3]), int.Parse(c[4]), int.Parse(c[5]), int.Parse(c[6]),
                int.Parse(c[7]), c[8] == "1", c[10] == "1", int.Parse(c[16]), int.Parse(c[17])));
        }
        return rows;
    }

    /// <summary>
    /// Compares decoded planes against the fixture truth (the yuv file, or its SHA-256). Returns null when equal, else a
    /// description with the first differing plane and byte (the byte is only known when the full yuv is embedded; for the
    /// SHA-only pictures the caller adds a comparison against the CPU reference).
    /// </summary>
    private static string? CompareVp8Truth(string name, byte[] y, byte[] u, byte[] v, int width, int height)
    {
        var all = new byte[y.Length + u.Length + v.Length];
        Buffer.BlockCopy(y, 0, all, 0, y.Length);
        Buffer.BlockCopy(u, 0, all, y.Length, u.Length);
        Buffer.BlockCopy(v, 0, all, y.Length + u.Length, v.Length);
        int cw = (width + 1) / 2;
        if (HasEmbedded(Vp8LossyPrefix + name + ".yuv"))
        {
            var expected = ReadEmbedded(Vp8LossyPrefix + name + ".yuv");
            if (expected.Length != all.Length) return $"yuv length {all.Length} != expected {expected.Length}";
            for (int i = 0; i < expected.Length; i++)
            {
                if (expected[i] == all[i]) continue;
                string plane; int off, w;
                if (i < y.Length) { plane = "Y"; off = i; w = width; }
                else if (i < y.Length + u.Length) { plane = "U"; off = i - y.Length; w = cw; }
                else { plane = "V"; off = i - y.Length - u.Length; w = cw; }
                return $"first mismatch in {plane} plane at x={off % w} y={off / w}: got {all[i]}, expected {expected[i]}";
            }
            return null;
        }
        var expectedHash = System.Text.Encoding.ASCII.GetString(ReadEmbedded(Vp8LossyPrefix + name + ".sha256")).Trim();
        var hash = Convert.ToHexString(SHA256.HashData(all)).ToLowerInvariant();
        return hash == expectedHash ? null : $"sha256 {hash} != expected {expectedHash}";
    }

    [TestMethod]
    public void Vp8IntraPredictor4x4_VerticalLeft_LastTwoValuesFollowRfc6386()
    {
        // RFC 6386 B_VL_PRED: "the last two values do not strictly follow the pattern": B[2][3] = avg3(A4,A5,A6) and
        // B[3][3] = avg3(A5,A6,A7). The library had B[3][3] = avg3(A4,A5,A6), which only real lossy files exposed.
        var above = new byte[] { 0, 10, 20, 30, 40, 50, 60, 70, 80 };   // above[-1] = 0, above[0..7] = 10..80
        var left = new byte[4];
        var dst = new byte[16];
        Vp8IntraPredictor4x4.Predict(Vp8IntraMode4x4.BVlPred, above, 1, left, dst, 4);
        Equal((byte)((50 + 2 * 60 + 70 + 2) >> 2), dst[2 * 4 + 3], "B[2][3]");
        Equal((byte)((60 + 2 * 70 + 80 + 2) >> 2), dst[3 * 4 + 3], "B[3][3]");
        Equal((byte)((40 + 2 * 50 + 60 + 2) >> 2), dst[1 * 4 + 3], "B[1][3]");
    }

    [TestMethod]
    public void Vp8LossyFixtures_Manifest_CoversEveryKeyframeFeature()
    {
        // A corpus that silently stops covering a feature would make the decoder tests below meaningless.
        var rows = Vp8LossyManifest();
        var names = Vp8LossyFixtureNames();
        Equal(names.Length, rows.Count, "every .vp8 has a manifest row");
        True(rows.Count >= 90, $"only {rows.Count} fixtures");
        True(rows.Any(r => r.FilterType == 1 && r.FilterLevel > 0), "simple loop filter");
        True(rows.Any(r => r.FilterType == 0 && r.FilterLevel > 0), "normal loop filter");
        True(rows.Any(r => r.FilterLevel == 0), "loop filter level 0");
        True(rows.Count(r => r.Sharpness > 0 && r.FilterLevel > 0) >= 5, "sharpness > 0");
        True(rows.Any(r => r.LfDelta), "mode/ref loop filter deltas");
        True(rows.Any(r => r.Segmentation), "segmentation");
        for (int p = 1; p <= 3; p++) True(rows.Any(r => r.Log2Parts == p), $"{1 << p} token partitions");
        for (int v = 0; v <= 3; v++) True(rows.Any(r => r.Version == v), $"version {v}");
        True(rows.Any(r => r.Width == 1 && r.Height == 1), "1x1");
        True(rows.Any(r => r.Width % 16 != 0 && r.Height % 16 != 0), "non-multiple-of-16 sizes");
        True(rows.Any(r => r.Width >= 640 && r.Height >= 480), "640x480");
    }

    [TestMethod]
    public void Vp8LossyFixtures_CpuReference_MatchesFfmpeg_AllFixtures()
    {
        // The reference walker + Vp8LoopFilter against ffmpeg's decode of the SAME bytes.
        var failures = new List<string>();
        foreach (var name in Vp8LossyFixtureNames())
        {
            try
            {
                var frame = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
                var planes = Vp8KeyframeReference.Decode(frame);
                var diff = CompareVp8Truth(name, planes.Y, planes.U, planes.V, planes.Width, planes.Height);
                if (diff != null) failures.Add($"{name}: {diff}");
            }
            catch (Exception ex)
            {
                failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
            }
        }
        True(failures.Count == 0, $"{failures.Count} of {Vp8LossyFixtureNames().Length} VP8 fixtures failed:\n" + string.Join("\n", failures));
    }
}
